using System;

class C
{
    static void Test(Func<(Func<short>, int)> d)
    {
        Console.WriteLine("short");
    }

    static void Test(Func<(Func<byte>, int)> d)
    {
        Console.WriteLine("byte");
    }

    static void Main()
    {
        // this works
        Test(()=>(()=>(short)1, 1));

        // this works
        Test(()=>(()=>(byte)1, 1));

        // this does not
        Test(()=>(()=>1, 1));
    }
}

